<?php require 'app.php';need_school();$sid=school_id();$ids=assigned_class_ids();$q=db()->prepare('SELECT id,name,stream FROM classes WHERE school_id=? ORDER BY name,stream');$q->execute([$sid]);$classes=$q->fetchAll();$classId=(int)($_GET['class_id']??$_POST['class_id']??0);if(in_array(role(),['patron','matron'],true)&&!in_array($classId,$ids,true))$classId=0;$args=[$sid];$sql='SELECT st.*,c.name class_name,c.stream,s.name school_name,s.logo_url FROM students st JOIN schools s ON s.id=st.school_id LEFT JOIN classes c ON c.id=st.class_id WHERE st.school_id=?';if($classId){$sql.=' AND st.class_id=?';$args[]=$classId;}elseif(in_array(role(),['patron','matron'],true)){$sql.=' AND st.class_id IN ('.($ids?implode(',',array_fill(0,count($ids),'?')):'NULL').')';$args=array_merge($args,$ids);}else $sql.=' AND 1=0';$sql.=' ORDER BY c.name,c.stream,st.last_name,st.first_name';$rows=[];if($classId){$q=db()->prepare($sql);$q->execute($args);$rows=$q->fetchAll();}ob_start();?><div class="panel"><form method="get"><label>Select class</label><select name="class_id" required><option value="">Choose class</option><?php foreach($classes as $c):if(in_array(role(),['patron','matron'],true)&&!in_array((int)$c['id'],$ids,true))continue;?><option value="<?=$c['id']?>" <?=$classId===$c['id']?'selected':''?>><?=h($c['name'].' '.$c['stream'])?></option><?php endforeach;?></select><button>Load class cards</button></form><button onclick="window.print()">Print cards</button></div><div class="cards"><?php foreach($rows as $r):$token=db()->prepare('SELECT qr_token FROM id_cards WHERE student_id=?');$token->execute([$r['id']]);$qr=$token->fetchColumn();if(!$qr){$qr=bin2hex(random_bytes(32));db()->prepare('INSERT INTO id_cards(school_id,student_id,qr_token) VALUES(?,?,?)')->execute([$sid,$r['id'],$qr]);}?><div class="idcard"><div class="cardhead"><?php if($r['logo_url']):?><img src="<?=h($r['logo_url'])?>" style="width:30px;height:30px;object-fit:contain;vertical-align:middle;margin-right:8px"><?php endif;?><?=h($r['school_name'])?></div><div class="cardbody"><?php if($r['photo_url']):?><img src="<?=h($r['photo_url'])?>" alt="Student photo"><?php endif;?><div><b><?=h($r['first_name'].' '.$r['last_name'])?></b><p>Admission: <?=h($r['admission_number'])?></p><p>Class: <?=h(($r['class_name']??'').' '.($r['stream']??''))?></p><small>Academic year: <?=date('Y')?></small></div></div><div class="qr"><img style="width:72px;height:72px;float:right" alt="QR verification" src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&amp;data=<?=rawurlencode(((!empty($_SERVER['HTTPS'])?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').dirname($_SERVER['SCRIPT_NAME']).'/verify.php?token='.$qr))?>">Scan to verify student</div></div><?php endforeach;?></div><style>.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:18px}.idcard{background:white;border:2px solid #123f72;border-radius:10px;overflow:hidden;max-width:390px;min-height:190px}.cardhead{background:#123f72;color:white;text-align:center;padding:12px;font-weight:bold}.cardbody{display:flex;gap:15px;padding:14px}.cardbody img{width:90px;height:105px;object-fit:cover;border-radius:7px}.qr{border-top:1px solid #ddd;padding:8px;font-size:11px}@media print{.top,.nav,form,button,h1{display:none!important}.wrap{margin:0;max-width:none}.cards{grid-template-columns:repeat(2,1fr)}.idcard{break-inside:avoid}}</style><?php page('Print Student ID Cards',ob_get_clean());
